{"command":"python3 -c "
import csv

# Verify a few stops against stop_times
with open('outputs/t05_clean_stop_times.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    times_by_stop = {}
    for row in reader:
        sid = row['stop_id']
        if sid not in times_by_stop:
            times_by_stop[sid] = []
        times_by_stop[sid].append(row['departure_time'])

# Check some specific stops
for sid in ['5015050104', '5015050105', '125101209']:
    if sid in times_by_stop:
        times = times_by_stop[sid]
        print(f'Stop {sid}: {len(times)} departures, first={min(times)}, last={max(times)}')
    else:
        print(f'Stop {sid}: NOT FOUND in stop_times')
""}

